{{ config(materialized='table') }}

    with
    gl_balances as (
    select * from {{ ref("gl_balances") }}
),
gl_ledgers as (
    select * from {{ ref("gl_ledgers") }}
),
gl_code_combinations as (
    select * from {{ ref("gl_code_combinations") }}
),
gl_periods as (
    select * from {{ ref("gl_periods") }}
),
gl_daily_rates as (
    select * from {{ ref("gl_daily_rates") }}
),
ct_gl_balances_f_stg as (
    SELECT CAST(gl_balances_reusable_mapping_s.ledger_id AS VARCHAR) AS ledger_id, CAST(gl_code_combinations_reusable.code_combination_id AS VARCHAR) AS glcc_id, COALESCE(gl_periods_reusable_mapping_st.period_name, '0') || '~' || cledgers_reusable_mapping_stg.period_set_name AS period_id, CAST( COALESCE( TO_CHAR( CAST(gl_periods_reusable_mapping_st.end_date AS DATE), 'YYYYMMDD' ), '0' ) AS INTEGER ) AS period_dt_id, gl_balances_reusable_mapping_s.period_name AS period_name, gl_balances_reusable_mapping_s.period_year AS period_year, gl_balances_reusable_mapping_s.period_num AS period_num, cledgers_reusable_mapping_stg.name AS ledger_name, gl_code_combinations_reusable.segment1 AS segment1, gl_code_combinations_reusable.segment2 AS segment2, gl_code_combinations_reusable.segment3 AS segment3, gl_code_combinations_reusable.segment4 AS segment4, gl_code_combinations_reusable.segment5 AS segment5, gl_code_combinations_reusable.segment6 AS segment6, gl_code_combinations_reusable.segment7 AS segment7, gl_code_combinations_reusable.segment8 AS segment8, gl_code_combinations_reusable.segment9 AS segment9, gl_balances_reusable_mapping_s.currency_code AS currency_code, gl_balances_reusable_mapping_s.actual_flag AS actual_flag, CASE WHEN COALESCE(gl_balances_reusable_mapping_s.period_net_dr, 0) > COALESCE(gl_balances_reusable_mapping_s.period_net_cr, 0) THEN 'DB' ELSE 'CR' END AS db_cr_ind, gl_balances_reusable_mapping_s.translated_flag AS translated_flag, gl_balances_reusable_mapping_s.budget_version_id AS budget_version_id, gl_balances_reusable_mapping_s.encumbrance_type_id AS encumbrance_type_id, CAST(NULL AS VARCHAR(200)) AS encumbrance_type_name, CAST(NULL AS VARCHAR(200)) AS summary_account_flag, COALESCE(gl_balances_reusable_mapping_s.period_net_dr, 0) AS period_net_dr, COALESCE(gl_balances_reusable_mapping_s.period_net_cr, 0) AS period_net_cr, COALESCE(gl_balances_reusable_mapping_s.begin_balance_dr, 0) AS begin_balance_dr, COALESCE(gl_balances_reusable_mapping_s.begin_balance_cr, 0) AS begin_balance_cr, COALESCE(gl_balances_reusable_mapping_s.begin_balance_cr, 0) - COALESCE(gl_balances_reusable_mapping_s.begin_balance_dr, 0) AS begin_balance, ( COALESCE(gl_balances_reusable_mapping_s.begin_balance_cr, 0) - COALESCE(gl_balances_reusable_mapping_s.begin_balance_dr, 0) ) + ( COALESCE(gl_balances_reusable_mapping_s.period_net_cr, 0) - COALESCE(gl_balances_reusable_mapping_s.period_net_dr, 0) ) AS end_balance, COALESCE(gl_balances_reusable_mapping_s.period_net_cr, 0) - COALESCE(gl_balances_reusable_mapping_s.period_net_dr, 0) AS period_activity, COALESCE(gl_balances_reusable_mapping_s.quarter_to_date_dr, 0) AS qtr_to_date_dr, COALESCE(gl_balances_reusable_mapping_s.quarter_to_date_cr, 0) AS qtr_to_date_cr, COALESCE(gl_balances_reusable_mapping_s.period_net_dr, 0) * COALESCE(gl_daily_rates.conversion_rate, 1) AS period_net_dr_usd, COALESCE(gl_balances_reusable_mapping_s.period_net_cr, 0) * COALESCE(gl_daily_rates.conversion_rate, 1) AS period_net_cr_usd, ( COALESCE(gl_balances_reusable_mapping_s.begin_balance_cr, 0) - COALESCE(gl_balances_reusable_mapping_s.begin_balance_dr, 0) ) * COALESCE(gl_daily_rates.conversion_rate, 1) AS begin_balance_usd, ( ( COALESCE(gl_balances_reusable_mapping_s.begin_balance_cr, 0) - COALESCE(gl_balances_reusable_mapping_s.begin_balance_dr, 0) ) + ( COALESCE(gl_balances_reusable_mapping_s.period_net_cr, 0) - COALESCE(gl_balances_reusable_mapping_s.period_net_dr, 0) ) ) * COALESCE(gl_daily_rates.conversion_rate, 1) AS end_balance_usd, COALESCE(gl_daily_rates.conversion_rate, 1) AS conv_rate_to_usd, COALESCE(gl_daily_rates.CONVERSION_TYPE, 'Corporate') AS conv_rate_type, CAST(NULL AS DATE) AS creation_dt, gl_balances_reusable_mapping_s.last_update_date AS last_update_dt, CAST(NULL AS VARCHAR(200)) AS created_by, gl_balances_reusable_mapping_s.last_updated_by AS last_updated_by, COALESCE(CAST(gl_balances_reusable_mapping_s.ledger_id AS VARCHAR), '0') || '~' || COALESCE(CAST(gl_balances_reusable_mapping_s.code_combination_id AS VARCHAR), '0') || '~' || COALESCE(gl_balances_reusable_mapping_s.period_name, ' ') || '~' || COALESCE(gl_balances_reusable_mapping_s.actual_flag, ' ') || '~' || COALESCE(gl_balances_reusable_mapping_s.translated_flag, 'X') || '~' || COALESCE(gl_balances_reusable_mapping_s.currency_code, ' ') || '~' || COALESCE(CAST(gl_balances_reusable_mapping_s.budget_version_id AS VARCHAR), '0') AS integration_id, 1000 AS datasource_num_id, 'Y' AS active_flag, 'N' AS delete_flag FROM gl_balances gl_balances_reusable_mapping_s INNER JOIN gl_ledgers cledgers_reusable_mapping_stg ON gl_balances_reusable_mapping_s.LEDGER_ID = cledgers_reusable_mapping_stg.LEDGER_ID INNER JOIN gl_code_combinations gl_code_combinations_reusable ON gl_balances_reusable_mapping_s.CODE_COMBINATION_ID = gl_code_combinations_reusable.CODE_COMBINATION_ID INNER JOIN gl_periods gl_periods_reusable_mapping_st ON gl_periods_reusable_mapping_st.PERIOD_SET_NAME = cledgers_reusable_mapping_stg.PERIOD_SET_NAME AND gl_balances_reusable_mapping_s.PERIOD_NAME = gl_periods_reusable_mapping_st.PERIOD_NAME AND gl_balances_reusable_mapping_s.PERIOD_TYPE = gl_periods_reusable_mapping_st.PERIOD_TYPE LEFT JOIN gl_daily_rates gl_daily_rates ON ( gl_daily_rates.FROM_CURRENCY = gl_balances_reusable_mapping_s.CURRENCY_CODE AND gl_daily_rates.TO_CURRENCY = 'USD' AND gl_daily_rates.CONVERSION_TYPE = 'Corporate' AND CAST(gl_daily_rates.CONVERSION_DATE AS DATE) = CAST(gl_periods_reusable_mapping_st.end_date AS DATE) ) WHERE (1 = 1) AND ( COALESCE(gl_balances_reusable_mapping_s.translated_flag, 'X') IN ('Y', 'X', 'R') AND gl_balances_reusable_mapping_s.actual_flag IN ('A') AND gl_balances_reusable_mapping_s.template_id IS NULL AND CAST(gl_balances_reusable_mapping_s.last_update_date AS TIMESTAMP) >= CAST('$LAST_RUN_DATE$' AS TIMESTAMP) )
)
    select * from ct_gl_balances_f_stg;
